import { Bar } from "react-chartjs-2";

const data = {
  labels: ["Jobs", "Users", "Applications"],
  datasets: [
    {
      label: "Stats",
      data: [12, 19, 7],
      backgroundColor: ["#6366f1", "#22c55e", "#f97316"],
    },
  ],
};

function Dashboard() {
  return <Bar data={data} />;
}

export default Dashboard;
